questions.q:
What does isEquipmentAvailable() actually return, given this method?

isEquipmentAvailable: function(equipmentId) {
    var gr = new GlideRecord('x_acme_eqchk_request');
    gr.addQuery('equipment', equipmentId);
    gr.addQuery('state', 'IN', '2,3');
    gr.addQuery('active', true);
    gr.query();
    return !gr.hasNext();
}
